<script lang="ts">
 import {onMount,tick} from 'svelte';
 import {createNodalViewportProjection,resolveDraggedNodeDelta,updateNodePosition,type NodalGraphDocument} from '@konitif/nodal';
 import {projectNodalReadingGroups,nodalReadingConnectionPath,zoomNodalReadingViewport,readingNodeSize,nodalReadingPortPoint,type NodalReadingFlow,type NodalReadingGroup,type NodalReadingInterface} from './nodalReadingGroups';
 export let graph:NodalGraphDocument;
 export let framingKey='';
 /** Visibility is a reading preference; hidden cables remain in the supplied graph. */
 export let hiddenEdgeIds:string[]=[];
 export let compactControlPorts=false;
 export let flow:NodalReadingFlow='horizontal';
 export let edgeAppearance:Record<string,{color?:string;dash?:string;label?:string}>={};
 export let groupInterfaces:Record<string,readonly NodalReadingInterface[]>={};
 /** Appearance is provided by the subject's clock; this projection owns no animation clock. */
 export let nodeEffects:Record<string,{opacity:number;emphasis:number}>={};
 export let initialFocusNodeIds:string[]=[];
 export let onMoveNodes:(ids:string[],delta:{x:number;y:number})=>void=()=>{};
 export let selectedNodeId:string|null=null;
 export let selectedNodeIds:string[]=[];
 export let onSelectNodes:(ids:string[])=>void=()=>{};
 export let onSelectNode:(id:string|null)=>void=()=>{};
 /** Projection preference only; the host may persist it through its normal Tool state. */
 export let expandedGroupIds:string[]=[];
 export let onExpandedGroupsChange:(ids:string[])=>void=()=>{};
 let root:HTMLDivElement,width=360,height=450,x=16,y=16,zoom=.5,drag:{pointer:number;x:number;y:number}|null=null;
 let nodeDrag:{pointer:number;ids:string[];start:{x:number;y:number};graph:NodalGraphDocument}|null=null,preview:NodalGraphDocument|null=null,delta={x:0,y:0};
 let selectionBox:{pointer:number;start:{x:number;y:number};current:{x:number;y:number};additive:boolean}|null=null;
 $: selectedIds=new Set(selectedNodeIds.length?selectedNodeIds:selectedNodeId?[selectedNodeId]:[]);
 let fittedIdentity='',fitRequest=0;
 $: shown=preview??graph;
 $: projection=projectNodalReadingGroups(shown,expandedGroupIds,groupInterfaces,flow,compactControlPorts);
 $: visibleConnections=projection.connections.filter(edge=>!hiddenEdgeIds.includes(edge.id));
 $: identity=JSON.stringify([graph.id,flow,graph.nodes.map(n=>n.id),graph.groups.map(g=>[g.id,g.nodeIds]),framingKey]);
 $: if(identity!==fittedIdentity){fittedIdentity=identity;const request=++fitRequest;void tick().then(()=>{if(root&&request===fitRequest)fitPreferred();});}
 $: grid=createNodalViewportProjection({x,y,zoom,width,height});
 function fitFrames(frames:{x:number;y:number;width:number;height:number}[],readable=false){if(!frames.length)return;const minX=Math.min(...frames.map(f=>f.x)),minY=Math.min(...frames.map(f=>f.y)),maxX=Math.max(...frames.map(f=>f.x+f.width)),maxY=Math.max(...frames.map(f=>f.y+f.height));zoom=Math.max(readable?.5:.15,Math.min(1,(width-32)/Math.max(1,maxX-minX),(height-32)/Math.max(1,maxY-minY)));x=Math.max(16,(width-(maxX-minX)*zoom)/2)-minX*zoom;y=Math.max(16,(height-(maxY-minY)*zoom)/2)-minY*zoom;}
 function fit(){fitFrames([...projection.nodes.map(n=>({...n.position,...readingNodeSize})),...projection.groups.map(g=>g.frame)]);}
 function fitPreferred(){const focus=new Set(initialFocusNodeIds),frames=[...projection.nodes.filter(n=>focus.has(n.id)).map(n=>({...n.position,...readingNodeSize})),...projection.groups.filter(g=>g.nodeIds.some(id=>focus.has(id))&&!projection.groups.some(c=>c.depth>g.depth&&c.nodeIds.some(id=>focus.has(id)))).map(g=>g.frame)];if(frames.length)fitFrames(frames,true);else fit();}
 function readEffect(id:string,effects:typeof nodeEffects,running=false){const effect=effects[id];return{opacity:Math.max(0,Math.min(1,effect?.opacity??1)),emphasis:Math.max(0,Math.min(1,effect?.emphasis??(running?.8:0)))};}
 function groupEffect(group:NodalReadingGroup,effects:typeof nodeEffects){const values=group.nodeIds.map(id=>readEffect(id,effects,shown.nodes.find(n=>n.id===id)?.state?.status==='running'));return{opacity:Math.max(.15,...values.map(e=>e.opacity)),emphasis:Math.max(0,...values.map(e=>e.emphasis))};}
 function toggleGroup(id:string){cancel();expandedGroupIds=expandedGroupIds.includes(id)?expandedGroupIds.filter(value=>value!==id):[...expandedGroupIds,id];onExpandedGroupsChange([...expandedGroupIds]);}
 function down(event:PointerEvent){fitRequest++;if(event.button!==0||event.target instanceof Element&&event.target.closest('button'))return;if(event.ctrlKey){const point=worldPoint(event);selectionBox={pointer:event.pointerId,start:point,current:point,additive:event.shiftKey};root.setPointerCapture(event.pointerId);event.preventDefault();return;}drag={pointer:event.pointerId,x:event.clientX-x,y:event.clientY-y};root.setPointerCapture(event.pointerId);}
 function nodeDown(event:PointerEvent,ids:string[],select:string|null){fitRequest++;if(event.button!==0)return;event.preventDefault();event.stopPropagation();if(event.ctrlKey&&select){onSelectNodes(selectedIds.has(select)?[...selectedIds].filter(id=>id!==select):[...selectedIds,select]);return;}if(select&&!(selectedIds.has(select)&&selectedIds.size>1))onSelectNode(select);if(select&&selectedIds.has(select)&&selectedIds.size>1)ids=[...selectedIds];else if(!select){if(ids.every(id=>selectedIds.has(id)))ids=[...selectedIds];else onSelectNodes(ids);}nodeDrag={pointer:event.pointerId,ids,start:{x:event.clientX,y:event.clientY},graph};delta={x:0,y:0};(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);}
 function worldPoint(event:PointerEvent){const bounds=root.getBoundingClientRect();return{x:(event.clientX-bounds.left-x)/zoom,y:(event.clientY-bounds.top-y)/zoom};}
 function move(event:PointerEvent){if(selectionBox?.pointer===event.pointerId){selectionBox={...selectionBox,current:worldPoint(event)};return;}if(nodeDrag?.pointer===event.pointerId){delta=resolveDraggedNodeDelta({pointerStart:nodeDrag.start,pointerCurrent:{x:event.clientX,y:event.clientY},zoom});preview=updateNodePosition(nodeDrag.graph,nodeDrag.ids,delta);return;}if(drag?.pointer===event.pointerId){x=event.clientX-drag.x;y=event.clientY-drag.y;}}
 function up(){if(selectionBox){const {start,current,additive}=selectionBox,left=Math.min(start.x,current.x),right=Math.max(start.x,current.x),top=Math.min(start.y,current.y),bottom=Math.max(start.y,current.y);const hit=(f:{x:number;y:number;width:number;height:number})=>f.x<=right&&f.x+f.width>=left&&f.y<=bottom&&f.y+f.height>=top;const ids=new Set(additive?selectedIds:[]);for(const n of projection.nodes)if(hit({...n.position,...readingNodeSize}))ids.add(n.id);for(const g of projection.groups){if(!g.expanded&&hit(g.frame)||g.expanded&&left<=g.frame.x&&right>=g.frame.x+g.frame.width&&top<=g.frame.y&&bottom>=g.frame.y+g.frame.height)for(const id of g.nodeIds)ids.add(id);}onSelectNodes([...ids]);cancel();return;}if(nodeDrag&&(Math.abs(delta.x)+Math.abs(delta.y)>.1))onMoveNodes(nodeDrag.ids,delta);cancel();}
 function cancel(){selectionBox=null;nodeDrag=null;preview=null;drag=null;}
 function wheel(event:WheelEvent){fitRequest++;event.preventDefault();const bounds=root.getBoundingClientRect(),next=zoomNodalReadingViewport({x,y,zoom},{x:event.clientX-bounds.left,y:event.clientY-bounds.top},event.deltaY);x=next.x;y=next.y;zoom=next.zoom;}
 function nodeKey(event:KeyboardEvent,id:string){const axes:Record<string,number[]>={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,-10],ArrowDown:[0,10]};const point=axes[event.key];if(point){event.preventDefault();onMoveNodes([id],{x:point[0],y:point[1]});}}
 function groupPort(group:NodalReadingGroup,index:number,direction:'input'|'output'){const point=(direction==='input'?group.inputs:group.outputs)[index]?.point;if(point)return point;return flow==='horizontal'?{x:group.frame.x+(direction==='output'?group.frame.width:0),y:group.frame.y+52+index*20}:nodalReadingPortPoint(group.frame,direction==='input'?group.inputs:group.outputs,index,direction,flow,compactControlPorts&&!group.expanded);}
 function showGroupPort(group:NodalReadingGroup,index:number,direction:'input'|'output'){const ports=direction==='input'?group.inputs:group.outputs;return !compactControlPorts||group.expanded||ports[index].mode!=='control'||index===ports.findIndex(port=>port.mode==='control');}
 function nodePort(node:typeof graph.nodes[number],index:number,direction:'input'|'output'){return nodalReadingPortPoint({x:0,y:0,...readingNodeSize},direction==='input'?node.inputs:node.outputs,index,direction,flow);}
 onMount(()=>{let measured=false;const observer=new ResizeObserver(entries=>{const before={width,height};width=entries[0].contentRect.width;height=entries[0].contentRect.height;if(!measured){measured=true;fitPreferred();}else{x+=(width-before.width)/2;y+=(height-before.height)/2;}});observer.observe(root);return()=>observer.disconnect();});
</script>
<div class="nodal-reading" bind:this={root} role="application" aria-label="Graphe nodal" class:panning={drag!==null} style:background-size={`${grid.gridMinorScreenSize}px ${grid.gridMinorScreenSize}px`} style:background-position={`${grid.gridMinorOffsetX}px ${grid.gridMinorOffsetY}px`} on:pointerdown={down} on:pointermove={move} on:pointerup={up} on:pointercancel={cancel} on:wheel={wheel} on:dblclick={event=>{if(event.target===event.currentTarget){fitRequest++;onSelectNodes([]);onSelectNode(null);}}}>
 <div class="canvas" style:transform={`translate(${x}px,${y}px) scale(${zoom})`}>
 {#each projection.groups as group (group.id)}
  {#if group.expanded}<div class="group-frame" style:--nodal-emphasis={groupEffect(group,nodeEffects).emphasis} class:selected={group.nodeIds.every(id=>selectedIds.has(id))} role="group" aria-label={'Groupe ouvert : '+group.label} data-nodal-group={group.id} style:left={group.frame.x+'px'} style:top={group.frame.y+'px'} style:width={group.frame.width+'px'} style:height={group.frame.height+'px'}><button class="group-title" aria-expanded="true" on:pointerdown={event=>nodeDown(event,group.nodeIds,null)} on:dblclick|stopPropagation={()=>toggleGroup(group.id)} on:keydown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();toggleGroup(group.id);}}}>▾ {group.label}</button></div>{/if}
 {/each}
 <svg class="edges" width="2000" height="2000" aria-hidden="true">{#each visibleConnections as edge (edge.id)}<path d={nodalReadingConnectionPath(edge.points,edge.axis)} style:stroke={edgeAppearance[edge.id]?.color??'var(--color-accent-primary,#65b9ef)'} stroke-dasharray={edgeAppearance[edge.id]?.dash??''}><title>{edgeAppearance[edge.id]?.label??'Liaison de port'}</title></path>{/each}</svg>
 {#each projection.groups as group (group.id)}
  {#if !group.expanded}<button class="node group-node" class:selected={group.nodeIds.every(id=>selectedIds.has(id))} style:opacity={groupEffect(group,nodeEffects).opacity} style:--nodal-emphasis={groupEffect(group,nodeEffects).emphasis} aria-label={'Groupe : '+group.label} aria-expanded="false" data-nodal-group={group.id} style:left={group.frame.x+'px'} style:top={group.frame.y+'px'} style:width={group.frame.width+'px'} style:height={group.frame.height+'px'} on:pointerdown={event=>nodeDown(event,group.nodeIds,null)} on:dblclick|stopPropagation={()=>toggleGroup(group.id)} on:keydown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();toggleGroup(group.id);}}}><strong>▸ {group.label}</strong><span>{group.nodeIds.length} nœuds · double-clic pour ouvrir</span></button>{/if}
  {#each group.inputs as port,index (port.id)}{#if showGroupPort(group,index,'input')}<span class="group-port input" class:expanded={group.expanded} title={compactControlPorts&&!group.expanded&&port.mode==='control'?'Liaisons de contrôle regroupées · ouvrir le groupe pour le détail':port.label} style:left={groupPort(group,index,'input').x-5+'px'} style:top={groupPort(group,index,'input').y-5+'px'}></span>{/if}{/each}
  {#each group.outputs as port,index (port.id)}{#if showGroupPort(group,index,'output')}<span class="group-port output" class:expanded={group.expanded} title={compactControlPorts&&!group.expanded&&port.mode==='control'?'Liaisons de contrôle regroupées · ouvrir le groupe pour le détail':port.label} style:left={groupPort(group,index,'output').x-5+'px'} style:top={groupPort(group,index,'output').y-5+'px'}></span>{/if}{/each}
 {/each}
 {#each projection.nodes as node (node.id)}<button class="node" style:opacity={readEffect(node.id,nodeEffects).opacity} style:--nodal-emphasis={readEffect(node.id,nodeEffects,node.state?.status==='running').emphasis} class:completed={node.state?.status==='success'} class:failed={node.state?.status==='error'} class:selected={selectedIds.has(node.id)} class:running={node.state?.status==='running'} style:left={node.position.x+'px'} style:top={node.position.y+'px'} style:width={readingNodeSize.width+'px'} style:height={readingNodeSize.height+'px'} aria-pressed={selectedIds.has(node.id)} on:pointerdown={event=>{nodeDown(event,[node.id],node.id);}} on:click={event=>{if(!event.ctrlKey&&!(selectedIds.has(node.id)&&selectedIds.size>1))onSelectNode(node.id);}} on:keydown={event=>{nodeKey(event,node.id);}}><strong>{node.title}</strong><span>{node.source?.label??node.type}</span><div>{#each node.badges??[] as badge (badge.id)}<small>{badge.label}</small>{/each}</div>{#each node.inputs as port,index (port.id)}<i class="input" style:left={nodePort(node,index,'input').x+'px'} style:top={nodePort(node,index,'input').y+'px'} title={port.label}></i>{/each}{#each node.outputs as port,index (port.id)}<i class="output" style:left={nodePort(node,index,'output').x+'px'} style:top={nodePort(node,index,'output').y+'px'} title={port.label}></i>{/each}</button>{/each}
 {#if selectionBox}<div class="selection-box" style:left={Math.min(selectionBox.start.x,selectionBox.current.x)+'px'} style:top={Math.min(selectionBox.start.y,selectionBox.current.y)+'px'} style:width={Math.abs(selectionBox.current.x-selectionBox.start.x)+'px'} style:height={Math.abs(selectionBox.current.y-selectionBox.start.y)+'px'}></div>{/if}
 </div><button class="fit" on:click={fit}>Cadrer le graphe</button>{#if projection.diagnostics.length}<span class="diagnostic" role="status">{projection.diagnostics.join(' · ')}</span>{/if}
</div>
<svelte:window on:keydown={event=>{if(event.key==='Escape'&&selectionBox)cancel();}}/>
<style>
 .selection-box{position:absolute;pointer-events:none;border:1px solid var(--color-accent-primary,#65b9ef);background:color-mix(in srgb,var(--color-accent-primary,#65b9ef) 12%,transparent);z-index:4}
 .nodal-reading{position:relative;width:100%;height:100%;min-height:0;overflow:clip;touch-action:none;background-color:var(--color-background-canvas,#09121d);background-image:radial-gradient(var(--color-border-default,#354659) 1px,transparent 1px);cursor:grab}.panning{cursor:grabbing}.canvas{position:absolute;top:0;left:0;transform-origin:0 0}.edges{position:absolute;overflow:visible;pointer-events:none}path{fill:none;stroke:var(--color-accent-primary,#65b9ef);stroke-width:2.5}.node{position:absolute;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:8px;border:1px solid var(--color-border-default,#466079);border-left:4px solid var(--color-accent-primary,#65b9ef);border-radius:8px;background:var(--color-background-surface,#152536);color:var(--color-text-primary,#e3edf7);padding:12px;font:14px system-ui;cursor:pointer;text-align:left}.node span{font-size:10px;color:var(--color-text-secondary,#9eacbb)}small{font-size:11px;padding:3px 6px;background:var(--color-background-canvas,#09121d);border-radius:3px}.node,.group-frame{box-shadow:0 0 calc(var(--nodal-emphasis,0)*26px) color-mix(in srgb,var(--color-accent-primary,#65b9ef) 40%,transparent)}.node.completed{border-left-color:var(--color-success,#65ba91)}.node.failed{border-left-color:var(--color-danger,#db766e)}.selected{outline:2px solid var(--color-accent-primary,#65b9ef)}.running{border-left-color:var(--color-success,#76dbb0)}.input,.output{position:absolute;width:10px;height:10px;border-radius:50%;background:var(--color-accent-primary,#65b9ef)}i.input,i.output{transform:translate(-50%,-50%)}.fit{position:absolute;right:8px;bottom:8px;border:1px solid var(--color-border-default,#466079);background:var(--color-background-surface,#152536);color:var(--color-text-primary,#e3edf7);border-radius:4px;padding:5px 8px;cursor:pointer}.group-frame{position:absolute;border:2px solid var(--color-border-default,#466079);border-radius:12px;background:rgba(255,255,255,.05);pointer-events:none}.group-title{position:absolute;top:8px;left:14px;right:14px;pointer-events:auto;text-align:left;background:transparent;color:var(--color-text-primary);border:0;font:600 14px system-ui;cursor:pointer}.group-node{justify-content:flex-start;padding-top:12px;border-style:double;border-width:3px}.group-port{pointer-events:none;z-index:2;background:transparent}.group-port::before{content:"";position:absolute;inset:0;border-radius:50%;background:var(--color-accent-primary,#65b9ef);outline:1px solid var(--color-background-canvas,#09121d);}.diagnostic{position:absolute;left:8px;bottom:8px;max-width:65%;font:11px system-ui;color:var(--color-text-secondary)}
</style>
